        inlineNumber(row, 'A cada N anos', x.every, (v) => { x.every = v; }, 1, MAX_YEAR);
        check(card, 'Não ocupa dia da semana', x.intercalary, (v) => { x.intercalary = v; });
        const options = el(card, 'details', 'brpg-detail');
